-- International Trade Breakdown
INSERT INTO scenarios (id, name, description, initial_state, rules_definition, created_at, updated_at)
VALUES (
  '10000000-0000-4000-8000-000000000001',
  'International Trade Breakdown',
  'A major geopolitical dispute has triggered closure of the Strait of Hormuz to commercial traffic. Your company depends on this route for 60% of raw material imports. Port capacity has collapsed and shipping costs are spiking. Manage a cascading maritime logistics crisis through five decision rounds, balancing inventory survival against cash preservation and long-term supply chain resilience.',
  '{"phase":"initial","round":1,"max_rounds":5,"variables":{"port_capacity":35,"shipping_delay_days":0,"fuel_cost_index":145,"geopolitical_risk_level":4,"inventory_level":72,"cash_reserves":10000000,"supply_chain_disruption":true,"supplier_diversification":"single","insurance_coverage":"standard","demand_pressure":80,"customer_satisfaction":75},"active_events":[],"history":[]}'::jsonb,
  '{"phases":["initial","escalation","crisis","resolution"],"actors":[{"id":"port_authority","name":"Strait Port Authority","role":"regulatory","influence":0.9,"description":"Controls access to the affected strait. Unresponsive to commercial pressure; responds only to diplomatic channels."},{"id":"shipping_consortium","name":"Global Shipping Consortium","role":"logistics_partner","influence":0.7,"description":"Controls 80% of available alternate-route vessels. Expensive but reliable when engaged early."},{"id":"government_relations","name":"Government Relations Office","role":"diplomatic","influence":0.6,"description":"Can pursue diplomatic resolution but requires 2\u20133 rounds of negotiation. Reduces geopolitical_risk_level by 1 per engagement."},{"id":"insurance_underwriter","name":"Marine Insurance Underwriter","role":"financial","influence":0.5,"description":"Standard coverage excludes geopolitical closures. Enhanced coverage available at cost but covers rerouting premiums."},{"id":"alternative_supplier","name":"Secondary Regional Supplier","role":"supply","influence":0.4,"description":"15% lower quality but geographically unconstrained. Can be activated within 1 round at a one-time cost."},{"id":"financial_controller","name":"Internal Financial Controller","role":"internal","influence":0.8,"description":"Monitors cash reserves and enforces spending thresholds. Will escalate if cash_reserves drop below $4M."}],"decision_points":[{"id":"dp_port_response","phase":"initial","title":"Port Closure Response","description":"The strait closure has cut your primary shipping route. You must decide how to restore cargo flow within 72 hours before inventory begins critical depletion.","trigger_condition":null,"options":[{"id":"opt_reroute","label":"Reroute through Cape of Good Hope","keywords":["reroute","alternate","cape","detour","redirect","good hope"],"state_changes":{"phase":"escalation","variables":{"shipping_delay_days":18,"fuel_cost_index":185,"port_capacity":80,"cash_reserves":8500000}},"feedback":"Rerouting adds 18 days and $1.5M in fuel and port fees but restores cargo flow. Inventory will draw down during the delay. Geopolitical exposure reduced."},{"id":"opt_wait","label":"Wait for strait reopening","keywords":["wait","hold","standby","diplomatic","reopen","delay"],"state_changes":{"phase":"crisis","variables":{"shipping_delay_days":21,"inventory_level":48,"cash_reserves":9500000,"customer_satisfaction":55}},"feedback":"Waiting preserves cash but inventory has dropped to 48%. Customer satisfaction is eroding. Diplomatic resolution is uncertain \u2014 geopolitical risk remains elevated."},{"id":"opt_air_freight","label":"Air freight for critical cargo","keywords":["air","freight","fly","aviation","critical","express","fast"],"state_changes":{"phase":"escalation","variables":{"shipping_delay_days":3,"fuel_cost_index":220,"cash_reserves":7200000,"inventory_level":68,"demand_pressure":75}},"feedback":"Air freight bridges the critical gap in 3 days but costs $2.8M. Cash reserves are now stressed. Sustainable only for 1\u20132 rounds before financial limits force a change."},{"id":"opt_diplomatic","label":"Engage government diplomatic channel","keywords":["diplomatic","government","negotiate","relations","politics","embassy","bilateral"],"state_changes":{"phase":"escalation","variables":{"geopolitical_risk_level":3,"shipping_delay_days":12,"inventory_level":60,"cash_reserves":9800000}},"feedback":"Diplomatic engagement has reduced geopolitical risk by one level. Shipping delay is still 12 days during negotiations. Inventory continues to decline but the long-term outlook improves."}]},{"id":"dp_supplier_diversification","phase":"escalation","title":"Supplier Diversification Decision","description":"Your single-source supplier is now unable to guarantee delivery. Do you activate backup suppliers at cost, or maintain the primary relationship and accept the risk?","trigger_condition":null,"options":[{"id":"opt_activate_backup","label":"Activate regional backup supplier","keywords":["backup","secondary","regional","activate","alternative","second","diversify"],"state_changes":{"phase":"escalation","variables":{"supplier_diversification":"dual","inventory_level":65,"cash_reserves":6800000,"supply_chain_disruption":false}},"feedback":"Backup supplier is activated at a $1.4M setup cost. Inventory stabilises. Quality is 15% lower than primary but sufficient for continued operations. Disruption risk significantly reduced."},{"id":"opt_maintain_single","label":"Maintain single supplier and renegotiate terms","keywords":["single","maintain","renegotiate","primary","keep","original"],"state_changes":{"phase":"crisis","variables":{"inventory_level":42,"cash_reserves":7800000,"geopolitical_risk_level":4,"customer_satisfaction":45}},"feedback":"Renegotiation is ongoing but the primary supplier is unable to deliver through the blocked route. Inventory has dropped to 42%. Customer satisfaction is declining sharply."},{"id":"opt_multi_source","label":"Emergency multi-source procurement","keywords":["multi","multiple","spread","diverse","emergency","portfolio","broad"],"state_changes":{"phase":"resolution","variables":{"supplier_diversification":"multi","inventory_level":70,"cash_reserves":5500000,"supply_chain_disruption":false,"demand_pressure":70}},"feedback":"Multi-source procurement is expensive ($2.9M) but creates resilient supply architecture. Inventory recovers to 70%. Long-term exposure to single-route disruption is eliminated."},{"id":"opt_performance_bond","label":"Enforce insurance performance bond","keywords":["insurance","bond","claim","enforce","underwriter","coverage"],"state_changes":{"phase":"escalation","variables":{"cash_reserves":8800000,"inventory_level":55,"insurance_coverage":"enhanced"}},"feedback":"Insurance bond claim partially accepted. $1M recovery reduces cash pressure. Inventory continues declining but financial runway is extended. Enhanced coverage now active for rerouting premiums."}]},{"id":"dp_fuel_hedging","phase":"escalation","title":"Fuel Cost Management","description":"Fuel costs are now 45\u2013120% above baseline. This is unsustainable over multiple rounds. How do you manage the fuel cost exposure?","trigger_condition":{"variable":"fuel_cost_index","operator":"gt","value":140},"options":[{"id":"opt_futures","label":"Lock in current rates via fuel futures contract","keywords":["futures","lock","hedge","contract","fixed","rate"],"state_changes":{"variables":{"fuel_cost_index":155,"cash_reserves":7500000}},"feedback":"Futures contract locks fuel at 155 index for 60 days at a $500K premium. Protected from further spikes. If rates fall, you overpay \u2014 but downside is capped."},{"id":"opt_pass_surcharge","label":"Pass fuel surcharge to customers","keywords":["pass","surcharge","customer","price","increase","transfer"],"state_changes":{"variables":{"fuel_cost_index":145,"customer_satisfaction":50,"demand_pressure":65,"cash_reserves":8200000}},"feedback":"Surcharge preserves margins but customer satisfaction drops to 50 and demand eases. 2 key accounts have flagged intent to seek alternative suppliers."},{"id":"opt_absorb","label":"Absorb fuel costs from cash reserves","keywords":["absorb","reserves","internal","sustain","maintain","cover"],"state_changes":{"variables":{"fuel_cost_index":145,"cash_reserves":6500000,"customer_satisfaction":80,"demand_pressure":82}},"feedback":"Absorbing costs protects customer relationships (satisfaction at 80) but burns $1.7M from reserves. Cash runway is now constrained to approximately 2 further rounds at this burn rate."}]},{"id":"dp_crisis_response","phase":"crisis","title":"Crisis Escalation Response","description":"The supply chain is in critical state. Inventory and cash are both stressed. An emergency decision is required to prevent operational failure.","trigger_condition":null,"options":[{"id":"opt_govt_intervention","label":"Request government emergency logistics intervention","keywords":["government","intervention","emergency","federal","state","military","strategic"],"state_changes":{"phase":"resolution","variables":{"port_capacity":65,"shipping_delay_days":8,"geopolitical_risk_level":2,"cash_reserves":7000000,"inventory_level":55}},"feedback":"Government intervention has partially opened the strait to humanitarian and critical commercial traffic. Port capacity is at 65%. Geopolitical risk reduced to level 2. Inventory stabilising."},{"id":"opt_charter_vessels","label":"Charter vessels from competitor operator","keywords":["charter","vessel","competitor","rival","rent","lease","ship"],"state_changes":{"phase":"resolution","variables":{"shipping_delay_days":5,"cash_reserves":6000000,"inventory_level":62,"port_capacity":60}},"feedback":"Chartered competitor vessels at premium cost ($1.5M). Delivery restored within 5 days. Cash is significantly reduced but operations can continue."},{"id":"opt_partial_delivery","label":"Accept partial delivery schedule and ration supply","keywords":["partial","ration","reduce","prioritise","triage","cut","schedule"],"state_changes":{"phase":"crisis","variables":{"inventory_level":50,"customer_satisfaction":40,"demand_pressure":55,"cash_reserves":8500000}},"feedback":"Rationing supply preserves cash but further damages customer relationships. Satisfaction drops to 40. Two major accounts have formally complained. Some demand has permanently shifted to competitors."}]},{"id":"dp_inventory_triage","phase":null,"title":"Emergency Inventory Management","description":"Inventory levels have dropped below the critical 50% threshold. Immediate action is required to prevent operational shutdown.","trigger_condition":{"variable":"inventory_level","operator":"lt","value":50},"options":[{"id":"opt_ration_key_customers","label":"Ration supply to key strategic customers only","keywords":["ration","key","strategic","priority","allocate","tier"],"state_changes":{"variables":{"customer_satisfaction":48,"demand_pressure":60,"cash_reserves":8800000,"inventory_level":45}},"feedback":"Rationing protects your 5 highest-value accounts but secondary customers have begun defecting. Short-term cash position is preserved."},{"id":"opt_emergency_procurement","label":"Emergency spot-market procurement at premium","keywords":["spot","emergency","premium","procure","buy","purchase","urgent"],"state_changes":{"variables":{"inventory_level":68,"cash_reserves":5800000,"supply_chain_disruption":false}},"feedback":"Spot-market procurement at 40% premium restores inventory to 68%. Expensive ($2.2M) but prevents immediate operational crisis."},{"id":"opt_halt_non_critical","label":"Halt non-critical operations to extend inventory runway","keywords":["halt","stop","pause","suspend","non-critical","reduce","operations"],"state_changes":{"variables":{"demand_pressure":45,"cash_reserves":9200000,"inventory_level":55,"customer_satisfaction":35}},"feedback":"Halting non-critical lines extends inventory runway by 3 weeks but customer satisfaction has collapsed. Significant revenue loss expected."}]}],"event_triggers":[{"id":"evt_fuel_spike","condition":{"variable":"fuel_cost_index","operator":"gt","value":190},"event":{"type":"fuel_price_spike","title":"Extreme Fuel Price Spike","description":"Fuel prices have exceeded 190% of baseline. An automatic $400K additional cost is incurred this round.","severity":"high","variable_changes_delta":{"cash_reserves":-400000}}},{"id":"evt_sanctions_risk","condition":{"variable":"geopolitical_risk_level","operator":"gte","value":4},"event":{"type":"secondary_sanctions_risk","title":"Secondary Sanctions Risk Warning","description":"Legal counsel advises that some alternate suppliers may trigger secondary sanctions exposure. Insurance underwriter has flagged the policy.","severity":"medium","variable_changes_delta":{}}},{"id":"evt_shortage_alert","condition":{"variable":"inventory_level","operator":"lt","value":35},"event":{"type":"critical_shortage_alert","title":"Critical Inventory Shortage Alert","description":"Internal systems have triggered a Tier 1 shortage alert. All non-essential procurement suspended. Finance committee notified.","severity":"critical","variable_changes_delta":{"customer_satisfaction":-8}}},{"id":"evt_cascade_failure","condition":{"variable":"shipping_delay_days","operator":"gte","value":20},"event":{"type":"supply_chain_cascade","title":"Cascading Supply Chain Failure","description":"Extended shipping delays have triggered cascading failures in downstream production. Subcontractors are requesting force majeure provisions.","severity":"critical","variable_changes_delta":{"inventory_level":-8,"customer_satisfaction":-10}}},{"id":"evt_cash_warning","condition":{"variable":"cash_reserves","operator":"lt","value":6000000},"event":{"type":"financial_distress_warning","title":"Financial Distress Warning","description":"Cash reserves have dropped below $6M. The financial controller has escalated to the CFO. Credit facility review initiated.","severity":"high","variable_changes_delta":{}}}],"outcome_conditions":[{"id":"oc_collapse","condition":{"variable":"inventory_level","operator":"lt","value":10},"outcome":"supply_chain_collapse","severity":"catastrophic","description":"Supply chain has completely collapsed. Operations suspended. Emergency board meeting convened. Regulatory and contractual penalties triggered."},{"id":"oc_operational_crisis","condition":{"variable":"cash_reserves","operator":"lt","value":3000000},"outcome":"financial_crisis","severity":"critical","description":"Cash reserves have dropped below $3M. Immediate access to credit facilities required. Operations under severe financial stress."},{"id":"oc_customer_loss","condition":{"variable":"customer_satisfaction","operator":"lt","value":30},"outcome":"major_customer_defection","severity":"high","description":"Customer satisfaction has collapsed below 30. Formal contract termination notices received from three major accounts."},{"id":"oc_stabilised","condition":{"variable":"inventory_level","operator":"gte","value":70,"and":{"variable":"shipping_delay_days","operator":"lt","value":7}},"outcome":"operations_stabilised","severity":"success","description":"Supply chain has stabilised. Inventory is at 70%+ with minimal shipping delays. Normal operations are resuming."},{"id":"oc_full_recovery","condition":{"variable":"inventory_level","operator":"gte","value":80,"and":{"variable":"cash_reserves","operator":"gte","value":7000000}},"outcome":"full_recovery","severity":"success","description":"Full operational recovery achieved. Inventory restored, financials healthy, and supply chain architecture strengthened."}]}'::jsonb,
  NOW(),
  NOW()
);

-- National Infrastructure Failure
INSERT INTO scenarios (id, name, description, initial_state, rules_definition, created_at, updated_at)
VALUES (
  '10000000-0000-4000-8000-000000000002',
  'National Infrastructure Failure',
  'A coordinated cyber attack has crippled the eastern seaboard power grid, cascading into partial failures across water treatment networks and emergency communications. 2.5 million people are affected. Hospitals are on backup power. The attack vector is partially identified but not contained. Coordinate a multi-agency response under time pressure, incomplete information, and public scrutiny across six decision rounds.',
  '{"phase":"initial","round":1,"max_rounds":6,"variables":{"power_grid_status":22,"water_system_status":58,"communications_status":65,"affected_population":2500000,"time_elapsed_hours":0,"agency_coordination_level":18,"public_trust":62,"resource_availability":78,"medical_facility_status":88,"information_confidence":35,"cyber_threat_contained":false,"emergency_declared":false,"public_unrest_level":10},"active_events":[],"history":[]}'::jsonb,
  '{"phases":["initial","triage","coordination","recovery","normalization"],"actors":[{"id":"emergency_director","name":"Emergency Management Director","role":"command","influence":0.95,"description":"Top-level authority over cross-agency coordination. Can unlock federal resources with emergency declaration but creates immediate media attention."},{"id":"grid_operator","name":"Regional Grid Operator (NERC)","role":"technical","influence":0.8,"description":"Controls physical restoration of the power grid. Restoration timeline depends on whether the cyber threat is isolated first."},{"id":"water_authority","name":"Metropolitan Water Authority","role":"utility","influence":0.7,"description":"Water treatment is 58% operational on auxiliary power. If power is not restored within 18 hours, chemical dosing systems fail."},{"id":"national_guard","name":"National Guard Commander","role":"resource_deployment","influence":0.75,"description":"Can deploy 4,000 personnel for logistics, security, and distribution. Requires emergency declaration to activate at full scale."},{"id":"public_health","name":"Public Health Officer","role":"medical","influence":0.7,"description":"Monitors hospital capacity and population health. Triggers mass casualty protocols if medical_facility_status falls below 50."},{"id":"communications_director","name":"Communications Director","role":"public_messaging","influence":0.65,"description":"Shapes public narrative. Full disclosure builds trust but risks panic. Managed messaging risks cover-up accusations."},{"id":"cyber_agency","name":"National Cyber Security Agency","role":"technical_intelligence","influence":0.6,"description":"Currently at 35% confidence on attack attribution. Needs 2 rounds to reach 70% confidence. Recommends isolating affected systems before restoration."},{"id":"hospital_admin","name":"Regional Hospital Network Administrator","role":"critical_care","influence":0.5,"description":"Hospitals have 12\u201318 hours of backup generator fuel. Requesting priority power restoration and fuel resupply."}],"decision_points":[{"id":"dp_initial_response","phase":"initial","title":"Immediate Crisis Response Declaration","description":"The attack was confirmed 4 hours ago. Initial assessments are incomplete (35% confidence). You must decide the official response posture within the next 2 hours before public media cycles begin.","trigger_condition":null,"options":[{"id":"opt_national_emergency","label":"Declare national emergency \u2014 full federal resource activation","keywords":["national","emergency","federal","full","declare","maximum","activate"],"state_changes":{"phase":"triage","variables":{"emergency_declared":true,"resource_availability":95,"agency_coordination_level":45,"public_trust":58,"public_unrest_level":25,"time_elapsed_hours":2}},"feedback":"National emergency declared. Federal resources unlocked \u2014 FEMA, National Guard, and strategic reserves activated. Resource availability surges to 95%. However, media coverage has intensified and public unrest level has risen. Early panic buying reported at fuel stations."},{"id":"opt_regional_emergency","label":"Declare regional state of emergency \u2014 balanced response","keywords":["regional","state","balanced","moderate","controlled","partial"],"state_changes":{"phase":"triage","variables":{"emergency_declared":true,"resource_availability":85,"agency_coordination_level":35,"public_trust":65,"public_unrest_level":15,"time_elapsed_hours":2}},"feedback":"Regional emergency declared. State-level resources activated including National Guard partial deployment. Balanced public messaging has maintained relative calm. Federal support available on request within 4\u20136 hours."},{"id":"opt_internal_response","label":"Handle internally \u2014 no formal emergency declaration yet","keywords":["internal","quiet","no declaration","handle","manage","contain","without"],"state_changes":{"phase":"triage","variables":{"emergency_declared":false,"resource_availability":70,"agency_coordination_level":22,"public_trust":70,"public_unrest_level":8,"time_elapsed_hours":3}},"feedback":"No formal declaration. Inter-agency coordination is slow and resources are limited. Public calm is maintained for now, but hospitals have flagged that generator fuel is running low. 3 hours have elapsed without formal coordination authority."}]},{"id":"dp_resource_prioritisation","phase":"triage","title":"Emergency Resource Prioritisation","description":"Resources are finite and infrastructure needs exceed capacity. You must decide which systems receive priority restoration support in the next operational cycle.","trigger_condition":null,"options":[{"id":"opt_priority_medical","label":"Prioritise hospitals and medical facilities","keywords":["hospital","medical","health","patient","care","clinical","priority"],"state_changes":{"variables":{"medical_facility_status":98,"power_grid_status":28,"water_system_status":52,"resource_availability":68,"time_elapsed_hours":6}},"feedback":"Hospital generator fuel resupply and dedicated circuit prioritisation has brought medical_facility_status to 98%. Power grid and water system continue degrading as other priorities take resources. Public health crisis averted for now."},{"id":"opt_priority_water","label":"Prioritise water treatment infrastructure","keywords":["water","treatment","sanitation","public health","chemical","dosing"],"state_changes":{"variables":{"water_system_status":78,"power_grid_status":25,"medical_facility_status":75,"resource_availability":65,"time_elapsed_hours":6}},"feedback":"Water treatment restored to 78% \u2014 chemical dosing systems secured. A public health catastrophe from contamination is avoided. Hospitals have burned through additional generator reserves; medical_facility_status has dropped to 75%."},{"id":"opt_priority_comms","label":"Prioritise communications restoration","keywords":["communications","comms","radio","broadcast","network","phone","911","emergency services"],"state_changes":{"variables":{"communications_status":88,"agency_coordination_level":55,"public_trust":72,"power_grid_status":22,"resource_availability":66,"time_elapsed_hours":5}},"feedback":"Emergency communications restored to 88%. Agency coordination improves significantly to 55 \u2014 inter-agency information flow is now reliable. 911 services fully operational. Public trust increases as information becomes available."},{"id":"opt_balanced_allocation","label":"Balanced allocation across all critical systems","keywords":["balanced","all","equal","spread","across","comprehensive","holistic"],"state_changes":{"variables":{"power_grid_status":28,"water_system_status":65,"communications_status":72,"medical_facility_status":82,"agency_coordination_level":42,"resource_availability":60,"time_elapsed_hours":7}},"feedback":"Balanced allocation improves all systems incrementally but none reach critical recovery thresholds. Overall resilience is distributed but fragile. No single system is now at immediate risk of collapse."}]},{"id":"dp_communications_strategy","phase":"triage","title":"Public Communications Strategy","description":"Media is requesting a full briefing. The public is increasingly anxious. You have incomplete attack information (35% confidence). How do you communicate?","trigger_condition":null,"options":[{"id":"opt_full_disclosure","label":"Full public disclosure \u2014 transparent briefing on all known facts","keywords":["full","transparent","disclose","honest","open","all facts","truth"],"state_changes":{"variables":{"public_trust":78,"public_unrest_level":30,"information_confidence":40,"agency_coordination_level":48}},"feedback":"Transparency has built trust \u2014 public_trust rises to 78. However, disclosure of grid vulnerability details has caused hoarding and some localised unrest. Cyber security agency warns that disclosed technical details may assist the attacker."},{"id":"opt_managed_messaging","label":"Managed messaging \u2014 controlled narrative, withhold technical details","keywords":["managed","controlled","partial","selective","narrative","strategic"],"state_changes":{"variables":{"public_trust":60,"public_unrest_level":18,"information_confidence":35,"agency_coordination_level":38}},"feedback":"Controlled messaging maintains calm but media are questioning the withheld details. Public trust remains at 60. Two journalists have obtained partial information from agency leaks \u2014 cover-up risk is emerging."},{"id":"opt_emergency_broadcast","label":"Emergency broadcast only \u2014 minimal information, actionable instructions","keywords":["broadcast","minimal","essential","instructions","emergency alert","basic","simple"],"state_changes":{"variables":{"public_trust":52,"public_unrest_level":22,"information_confidence":35,"agency_coordination_level":32}},"feedback":"Emergency broadcast provides instructions but no context. Public frustration is building \u2014 social media speculation is filling the information vacuum. Trust is declining. Unrest moderate."}]},{"id":"dp_agency_command","phase":"coordination","title":"Inter-Agency Command Structure","description":"With multiple agencies responding, coordination is still fragmented. A command structure decision is needed to align resources.","trigger_condition":{"variable":"agency_coordination_level","operator":"lt","value":65},"options":[{"id":"opt_unified_command","label":"Establish unified incident command (ICS/NIMS)","keywords":["unified","command","ICS","NIMS","centralise","single","structure"],"state_changes":{"phase":"coordination","variables":{"agency_coordination_level":80,"resource_availability":88,"time_elapsed_hours":10,"information_confidence":55}},"feedback":"Unified incident command established under ICS framework. Agency coordination jumps to 80. Information flow is now structured and duplicated efforts eliminated. Takes 3 hours to stand up \u2014 time has advanced."},{"id":"opt_lead_agency","label":"Lead agency model \u2014 Emergency Management Director takes command","keywords":["lead","lead agency","director","authority","command","single agency","lead authority"],"state_changes":{"phase":"coordination","variables":{"agency_coordination_level":65,"resource_availability":80,"time_elapsed_hours":8,"information_confidence":48}},"feedback":"Lead agency model established quickly. Director now has decision authority but three agencies have flagged jurisdictional concerns. Coordination is improved but not optimal \u2014 interoperability issues remain."},{"id":"opt_federated","label":"Federated coordination \u2014 agencies retain autonomy, share liaison officers","keywords":["federated","federate","autonomous","liaison","decentralised","independent","cooperative"],"state_changes":{"phase":"coordination","variables":{"agency_coordination_level":48,"resource_availability":72,"time_elapsed_hours":7,"information_confidence":42}},"feedback":"Federated model preserves agency autonomy and is implemented quickly. However, resource allocation conflicts continue and information remains siloed. Two agencies are executing conflicting recovery priorities."}]},{"id":"dp_cyber_response","phase":"coordination","title":"Cyber Threat Remediation Strategy","description":"The cyber security agency has reached 55\u201370% confidence on the attack vector. A remediation decision is now required before grid restoration can proceed safely.","trigger_condition":{"variable":"information_confidence","operator":"gte","value":45},"options":[{"id":"opt_isolate_first","label":"Isolate all affected systems before restoration","keywords":["isolate","air gap","disconnect","secure","contain","safe","first"],"state_changes":{"phase":"recovery","variables":{"cyber_threat_contained":true,"power_grid_status":42,"information_confidence":85,"time_elapsed_hours":16}},"feedback":"Systems isolated. Threat contained. Grid restoration can now proceed without risk of re-infection. Isolation took 6 additional hours but the recovery path is now clean and secure."},{"id":"opt_patch_concurrent","label":"Patch and restore concurrently \u2014 accept residual risk","keywords":["concurrent","simultaneous","parallel","patch","restore","both","together","faster"],"state_changes":{"phase":"recovery","variables":{"power_grid_status":55,"information_confidence":60,"time_elapsed_hours":12,"cyber_threat_contained":false}},"feedback":"Concurrent patching and restoration accelerates recovery \u2014 grid at 55% in 4 hours less than isolation approach. However, residual malware has been detected in 2 substations. Reinfection risk remains elevated."},{"id":"opt_federal_cyber","label":"Request federal cyber assistance before action","keywords":["federal","CISA","NSA","federal assistance","specialist","expert","outside help"],"state_changes":{"phase":"coordination","variables":{"information_confidence":90,"cyber_threat_contained":true,"time_elapsed_hours":20,"power_grid_status":35}},"feedback":"Federal cyber specialists arrived and fully characterised the attack within 6 hours. Threat attribution at 90% confidence. Clean remediation path identified but 8 additional hours elapsed. Grid restoration delayed."}]},{"id":"dp_recovery_communication","phase":"recovery","title":"Public Recovery Timeline Commitment","description":"Media is demanding a restoration timeline. Your technical teams have given you a range of 48 hours to 8 days depending on risk posture. What do you communicate publicly?","trigger_condition":null,"options":[{"id":"opt_aggressive_timeline","label":"Commit to aggressive 48-hour full restoration timeline","keywords":["48","aggressive","fast","rapid","optimistic","48 hours","two days"],"state_changes":{"phase":"normalization","variables":{"public_trust":80,"public_unrest_level":12,"power_grid_status":72,"agency_coordination_level":85}},"feedback":"Public confidence boosted by decisive commitment. Teams are under pressure to deliver. If the 48-hour target is missed, the credibility impact will be severe. Current trajectory suggests 60\u201370% grid restoration within the window."},{"id":"opt_moderate_timeline","label":"Moderate 5-day estimate with daily public updates","keywords":["moderate","five days","5 days","realistic","daily","update","transparent progress"],"state_changes":{"phase":"normalization","variables":{"public_trust":72,"public_unrest_level":18,"power_grid_status":65,"agency_coordination_level":80}},"feedback":"Moderate timeline is credible and allows operational flexibility. Daily briefings maintain public confidence. Some impatience but no significant unrest. Trust holding steady at 72."},{"id":"opt_conservative_timeline","label":"Conservative estimate with full uncertainty disclosure","keywords":["conservative","uncertain","honest","unknown","best effort","no commitment","range"],"state_changes":{"phase":"normalization","variables":{"public_trust":65,"public_unrest_level":28,"power_grid_status":58,"agency_coordination_level":75}},"feedback":"Full uncertainty disclosure maintains honesty but increases public anxiety. Unrest level has risen to 28. The media has characterised the response as ''confused''. Opposition parties are calling for an independent inquiry."}]}],"event_triggers":[{"id":"evt_public_health_emergency","condition":{"variable":"water_system_status","operator":"lt","value":40},"event":{"type":"public_health_emergency","title":"Public Health Emergency \u2014 Water Contamination Risk","description":"Water treatment has fallen below safe operational threshold. Chemical dosing failure detected. Boil-water advisory issued across 3 municipalities.","severity":"critical","variable_changes_delta":{"public_unrest_level":20,"public_trust":-12}}},{"id":"evt_public_unrest","condition":{"variable":"public_unrest_level","operator":"gte","value":45},"event":{"type":"civil_unrest_incident","title":"Civil Unrest Incidents Reported","description":"Police report civil disturbances at 4 distribution points. National Guard deployment requested to maintain order. Operational resources diverted.","severity":"high","variable_changes_delta":{"resource_availability":-12,"agency_coordination_level":-8}}},{"id":"evt_hospital_critical","condition":{"variable":"medical_facility_status","operator":"lt","value":55},"event":{"type":"hospital_critical_alert","title":"Hospital Network Critical Alert","description":"Three hospitals have declared internal emergencies. Elective procedures suspended. Emergency department diversions in effect. Two ICU patients at risk.","severity":"critical","variable_changes_delta":{"public_trust":-15,"public_unrest_level":15}}},{"id":"evt_coordination_breakdown","condition":{"variable":"agency_coordination_level","operator":"lt","value":25},"event":{"type":"coordination_breakdown","title":"Inter-Agency Coordination Breakdown","description":"Emergency Management Director reports that two agencies have begun independent operations conflicting with the unified response plan. Resource duplication detected.","severity":"high","variable_changes_delta":{"resource_availability":-15,"time_elapsed_hours":3}}},{"id":"evt_grid_momentum","condition":{"variable":"power_grid_status","operator":"gte","value":65},"event":{"type":"recovery_momentum","title":"Grid Recovery Momentum Achieved","description":"Power restoration above 65% creates cascading improvements \u2014 water treatment pumps restart, emergency communications improve, and hospitals reduce generator dependency.","severity":"positive","variable_changes_delta":{"water_system_status":12,"communications_status":10,"medical_facility_status":8}}},{"id":"evt_cyber_reinfection","condition":{"variable":"cyber_threat_contained","operator":"eq","value":false},"event":{"type":"cyber_reinfection_detected","title":"Cyber Reinfection Detected","description":"Malware re-propagation detected in grid control systems during restoration. Emergency cyber isolation protocols activated, setting back recovery by several hours.","severity":"high","variable_changes_delta":{"power_grid_status":-18,"information_confidence":-10}}}],"outcome_conditions":[{"id":"oc_mass_casualty","condition":{"variable":"medical_facility_status","operator":"lt","value":30},"outcome":"mass_casualty_event","severity":"catastrophic","description":"Hospital network has collapsed below safe operating threshold. Mass casualty protocols declared. Federal disaster declaration with full liability implications."},{"id":"oc_water_catastrophe","condition":{"variable":"water_system_status","operator":"lt","value":20},"outcome":"water_system_collapse","severity":"catastrophic","description":"Water treatment failure is complete. Public health emergency affecting 2.5M people. Multi-agency investigation and congressional hearings initiated."},{"id":"oc_public_confidence_lost","condition":{"variable":"public_trust","operator":"lt","value":25},"outcome":"loss_of_public_confidence","severity":"critical","description":"Public trust has collapsed. Government credibility crisis. Political leadership facing calls for resignation. Independent inquiry commissioned."},{"id":"oc_infrastructure_restored","condition":{"variable":"power_grid_status","operator":"gte","value":80,"and":{"variable":"water_system_status","operator":"gte","value":78}},"outcome":"infrastructure_restored","severity":"success","description":"Critical infrastructure has been restored to safe operational levels. Recovery operations transitioning to normalisation phase. Public confidence stabilising."},{"id":"oc_full_restoration","condition":{"variable":"power_grid_status","operator":"gte","value":90,"and":{"variable":"public_trust","operator":"gte","value":70}},"outcome":"full_restoration","severity":"success","description":"Full infrastructure restoration with maintained public trust. Crisis response widely viewed as effective. Post-incident review and lessons-learned process initiated."}]}'::jsonb,
  NOW(),
  NOW()
);

-- Internal Company Politics
INSERT INTO scenarios (id, name, description, initial_state, rules_definition, created_at, updated_at)
VALUES (
  '10000000-0000-4000-8000-000000000003',
  'Internal Company Politics',
  'The retiring CEO has created a leadership vacuum. Three powerful factions are competing for strategic control of the company: the Growth faction (VP Sales) pushing aggressive market expansion, the Stability faction (CFO) demanding profitability and cost reduction, and the Innovation faction (CTO) advocating a technology pivot. You are a senior director with cross-functional influence. Navigate six rounds of competing narratives, incomplete information, budget battles, and stakeholder conflict to steer the organisation toward a coherent outcome.',
  '{"phase":"initial","round":1,"max_rounds":6,"variables":{"stakeholder_alignment":32,"information_asymmetry":68,"executive_support":42,"team_morale":52,"budget_contested":8000000,"political_capital":50,"media_exposure_risk":22,"board_confidence":62,"talent_retention_risk":38,"faction_a_strength":62,"faction_b_strength":58,"faction_c_strength":44,"alliance_strength":0,"narrative_control":40},"active_events":[],"history":[]}'::jsonb,
  '{"phases":["initial","escalation","confrontation","resolution"],"actors":[{"id":"vp_sales","name":"VP Sales (Growth Faction Leader)","role":"internal_executive","influence":0.85,"description":"Drives aggressive market expansion agenda. Controls largest team and highest revenue line. Has board ear on growth metrics. Volatile under pressure."},{"id":"cfo","name":"CFO (Stability Faction Leader)","role":"internal_executive","influence":0.8,"description":"Controls budget approvals and financial narrative. Risk-averse. Has formal veto power on capital expenditure. Values process over speed."},{"id":"cto","name":"CTO (Innovation Faction Leader)","role":"internal_executive","influence":0.7,"description":"Controls technology roadmap. Respected technically but politically weaker. Holds leverage through key technical talent."},{"id":"board","name":"Board of Directors","role":"ultimate_authority","influence":1.0,"description":"Currently neutral. Will intervene if board_confidence falls below 35 or if conflict becomes public. Has final authority on CEO appointment."},{"id":"hr_director","name":"HR Director","role":"internal_mediator","influence":0.55,"description":"Monitors culture and talent. Raising concerns about talent_retention_risk. Can mediate conflict but has limited political capital."},{"id":"media_relations","name":"Media Relations Director","role":"external_narrative","influence":0.5,"description":"Controls external communications. Warns that media_exposure_risk is rising. Can suppress leaks for 1 round but not indefinitely."},{"id":"key_talent","name":"Key Technical and Commercial Talent Pool","role":"leverage","influence":0.6,"description":"High-value employees watching leadership dysfunction with growing anxiety. Three senior employees have been approached by competitors."},{"id":"consultant","name":"External Strategy Consultant","role":"wild_card","influence":0.45,"description":"Hired by the board to assess strategic options. Ostensibly neutral but known to favour the Stability faction CFO approach."}],"decision_points":[{"id":"dp_initial_positioning","phase":"initial","title":"Initial Strategic Positioning","description":"The CEO retirement has created an immediate power vacuum. All three factions are looking for allies. You must establish your positioning before the informal coalitions solidify. Your choice now will determine which stakeholders see you as aligned or opposed.","trigger_condition":null,"options":[{"id":"opt_back_growth","label":"Back the Growth faction publicly","keywords":["growth","sales","expansion","aggressive","back growth","VP sales","revenue"],"state_changes":{"phase":"escalation","variables":{"executive_support":62,"faction_a_strength":72,"faction_b_strength":52,"political_capital":65,"board_confidence":60,"team_morale":48}},"feedback":"Publicly backing Growth creates a clear signal. VP Sales is now a strong ally (executive_support: 62). CFO faction is now openly opposed. Board is watching but neutral. High-risk, high-reward positioning."},{"id":"opt_back_stability","label":"Back the Stability faction","keywords":["stability","CFO","conservative","safe","profit","cost","financial","back stability"],"state_changes":{"phase":"escalation","variables":{"executive_support":58,"faction_b_strength":70,"faction_a_strength":55,"political_capital":55,"board_confidence":68,"team_morale":50}},"feedback":"Backing Stability is the safe choice. CFO is now an ally. Board confidence is strong (68) \u2014 the CFO has board relationships. However, the Growth faction sees this as betrayal and team morale has softened."},{"id":"opt_back_innovation","label":"Back the Innovation faction","keywords":["innovation","CTO","technology","tech","R&D","pivot","future","back innovation"],"state_changes":{"phase":"escalation","variables":{"executive_support":48,"faction_c_strength":60,"team_morale":68,"talent_retention_risk":25,"board_confidence":58,"political_capital":45}},"feedback":"Innovation backing galvanises technical talent \u2014 team_morale surges to 68 and talent_retention_risk drops. The CTO is grateful. However, Innovation is the politically weakest faction. Executive support is limited."},{"id":"opt_neutral","label":"Remain neutral \u2014 position as independent broker","keywords":["neutral","independent","broker","mediator","no faction","remain","balance"],"state_changes":{"phase":"escalation","variables":{"political_capital":58,"information_asymmetry":55,"board_confidence":65,"executive_support":45,"narrative_control":55}},"feedback":"Neutrality preserves optionality and builds your reputation as an honest broker. Information_asymmetry drops as all factions brief you. Board confidence is stable. Risk: all factions may come to see you as unreliable when decisions are forced."}]},{"id":"dp_information_management","phase":"initial","title":"Information Gathering Strategy","description":"Each faction is controlling its own narrative. Information asymmetry is high (68). Before committing to further actions, you must decide how to close the information gap.","trigger_condition":null,"options":[{"id":"opt_transparency_audit","label":"Request a full transparency and information audit","keywords":["audit","transparency","full","disclose","open books","reveal","information audit"],"state_changes":{"variables":{"information_asymmetry":20,"political_capital":38,"executive_support":38,"narrative_control":65}},"feedback":"The audit reveals significant hidden agendas from all three factions. Information asymmetry drops to 20 \u2014 you now have a clear picture. Political cost is high: all factions resent the exposure. VP Sales is particularly hostile."},{"id":"opt_private_intel","label":"Conduct private intelligence gathering","keywords":["private","intel","intelligence","quiet","discreet","gather","informal","network"],"state_changes":{"variables":{"information_asymmetry":38,"political_capital":52,"alliance_strength":15,"narrative_control":52}},"feedback":"Private intelligence through your informal network reduces information asymmetry to 38. You have actionable insights on each faction without triggering defensive reactions. Political capital maintained."},{"id":"opt_accept_current","label":"Accept current information state and proceed","keywords":["accept","proceed","current","act now","move forward","incomplete","as is"],"state_changes":{"variables":{"information_asymmetry":68,"political_capital":60,"narrative_control":42}},"feedback":"Acting on incomplete information preserves speed and political capital. You retain full political flexibility. Risk: you may be making decisions based on factional disinformation. Information asymmetry remains at 68."}]},{"id":"dp_alliance_building","phase":"escalation","title":"Alliance Construction","description":"Factions are consolidating. You need to build a coalition if you want to influence the outcome. What is your alliance strategy?","trigger_condition":{"variable":"political_capital","operator":"gt","value":0},"options":[{"id":"opt_executive_coalition","label":"Form a formal executive coalition","keywords":["formal","coalition","executive","official","public","alliance","declare"],"state_changes":{"variables":{"alliance_strength":70,"executive_support":72,"narrative_control":65,"political_capital":35,"media_exposure_risk":45}},"feedback":"Formal coalition is powerful and visible. Alliance strength surges to 70. Executive support strong. However, media_exposure_risk rises to 45 \u2014 the coalition is now a public political entity subject to scrutiny."},{"id":"opt_informal_network","label":"Build informal network of allies","keywords":["informal","network","quiet","behind","relationships","soft power","cultivate"],"state_changes":{"variables":{"alliance_strength":45,"political_capital":44,"information_asymmetry":30,"media_exposure_risk":20,"board_confidence":68}},"feedback":"Informal network is slower but durable and harder to counter. Media exposure risk stays low. Information continues to flow to you. Alliance strength at 45 \u2014 sufficient for influence but not dominance."},{"id":"opt_board_appeal","label":"Appeal directly to the board of directors","keywords":["board","directors","escalate","appeal","governance","board level","trustees"],"state_changes":{"variables":{"board_confidence":75,"political_capital":28,"executive_support":35,"alliance_strength":55,"media_exposure_risk":55}},"feedback":"Board engagement is high-stakes. Board confidence rises to 75 \u2014 they appreciate the direct engagement. However, the move is read as bypassing the executive layer. Executive support drops. Media risk rises."},{"id":"opt_external_validator","label":"Engage external consultant as validator","keywords":["consultant","external","validator","advisor","third party","independent","outside"],"state_changes":{"variables":{"information_asymmetry":25,"political_capital":42,"board_confidence":70,"media_exposure_risk":18,"executive_support":48}},"feedback":"External consultant engagement lends credibility and provides cover for difficult positions. Board confidence improves. Note: the consultant is known to favour the Stability faction \u2014 their findings may be biased."}]},{"id":"dp_budget_battle","phase":"escalation","title":"Contested Budget Allocation","description":"The M in contested budget is now formally on the table. The CFO has called a budget committee meeting. Three factions each want a majority. Your position on this decision will define your faction alignment permanently in financial terms.","trigger_condition":{"variable":"budget_contested","operator":"gte","value":5000000},"options":[{"id":"opt_negotiate_split","label":"Negotiate a shared budget split","keywords":["split","share","negotiate","compromise","divide","equitable","fair"],"state_changes":{"variables":{"stakeholder_alignment":52,"political_capital":55,"executive_support":58,"budget_contested":2000000,"board_confidence":68}},"feedback":"Budget split negotiated. Stakeholder alignment rises to 52 \u2014 factions accept the compromise. Political capital is maintained. Board views the resolution favourably. M remains under dispute for the next cycle."},{"id":"opt_fight_for_control","label":"Fight for full budget control","keywords":["control","full","fight","win","dominate","all","maximum","total"],"state_changes":{"variables":{"political_capital":72,"executive_support":72,"stakeholder_alignment":22,"budget_contested":0,"team_morale":38,"media_exposure_risk":48}},"feedback":"Aggressive budget fight won. Full budget control achieved (M). Political capital surges but stakeholder alignment has collapsed to 22. Two executives have formally complained to the board. Team morale has deteriorated."},{"id":"opt_concede","label":"Concede contested budget, focus on different resources","keywords":["concede","give up","step back","yield","resources","different","reframe","redirect"],"state_changes":{"variables":{"political_capital":62,"stakeholder_alignment":58,"executive_support":52,"budget_contested":0,"board_confidence":65,"team_morale":60}},"feedback":"Conceding the budget battle is seen as gracious rather than weak. Stakeholder alignment improves significantly to 58. You have redirected your focus to headcount and project approval authority \u2014 often more powerful than budget."},{"id":"opt_performance_allocation","label":"Propose performance-based budget allocation","keywords":["performance","metric","KPI","results","outcome","data","merit"],"state_changes":{"variables":{"political_capital":58,"stakeholder_alignment":48,"board_confidence":74,"budget_contested":3000000,"narrative_control":65}},"feedback":"Performance-based framework proposed. Board loves it (confidence: 74). Factions are cautious \u2014 each believes they can win on metrics. M remains in escrow pending Q2 results. You control the evaluation framework."}]},{"id":"dp_conflict_response","phase":"confrontation","title":"Escalation Response \u2014 Open Conflict","description":"The conflict has become open. A divisive all-hands email from the VP Sales has exposed the internal disagreement publicly. HR has raised a formal concern. Board has requested an update within 48 hours.","trigger_condition":{"variable":"stakeholder_alignment","operator":"lt","value":35},"options":[{"id":"opt_hr_mediation","label":"Seek formal HR mediation","keywords":["HR","mediation","formal","human resources","mediate","process","neutral party"],"state_changes":{"phase":"resolution","variables":{"stakeholder_alignment":50,"team_morale":62,"talent_retention_risk":32,"political_capital":45,"media_exposure_risk":15}},"feedback":"HR mediation de-escalates the open conflict. Stakeholder alignment rises to 50 and team morale recovers. Media exposure risk reduced. Political cost is moderate \u2014 being seen to use HR signals weakness to some executives."},{"id":"opt_escalate_board","label":"Escalate to board \u2014 force resolution","keywords":["board","escalate","force","resolution","governance","intervention","board level"],"state_changes":{"phase":"resolution","variables":{"board_confidence":80,"stakeholder_alignment":42,"political_capital":35,"executive_support":40,"media_exposure_risk":65}},"feedback":"Board escalation forces immediate action. Board confidence rises to 80 \u2014 they appreciate the governance trigger. However, media_exposure_risk spikes to 65 as journalists detect board activity. Executives feel blindsided."},{"id":"opt_public_messaging","label":"Shape the narrative through public messaging","keywords":["public","message","narrative","communications","press","external","PR","announcement"],"state_changes":{"phase":"confrontation","variables":{"narrative_control":78,"media_exposure_risk":42,"stakeholder_alignment":38,"political_capital":55,"board_confidence":60}},"feedback":"External messaging puts your frame on the story. Narrative control rises to 78. Media exposure is managed but not eliminated. Internal stakeholders resent the external positioning \u2014 some see it as reputation management at the company''s expense."},{"id":"opt_quiet_diplomacy","label":"One-on-one quiet diplomacy with key stakeholders","keywords":["quiet","one-on-one","bilateral","diplomatic","private","individual","personal"],"state_changes":{"phase":"resolution","variables":{"stakeholder_alignment":48,"political_capital":62,"information_asymmetry":22,"alliance_strength":60,"executive_support":58,"media_exposure_risk":12}},"feedback":"Quiet diplomacy works gradually but effectively. Information asymmetry drops as stakeholders open up. Alliance strength builds to 60. Media risk stays low. This path is slow \u2014 it costs one additional round of conflict exposure."}]},{"id":"dp_endgame_strategy","phase":"resolution","title":"Endgame \u2014 Leadership Resolution","description":"The board has commissioned a formal leadership review. You have one final opportunity to shape the outcome. The CEO appointment is imminent. Your positioning in this final round will determine the long-term power structure.","trigger_condition":null,"options":[{"id":"opt_consolidated_leadership","label":"Push for consolidated single-faction leadership","keywords":["consolidated","single","clear winner","decisive","strong leadership","one leader"],"state_changes":{"phase":"resolution","variables":{"stakeholder_alignment":40,"board_confidence":78,"political_capital":80,"team_morale":55,"talent_retention_risk":50}},"feedback":"Consolidated leadership creates clarity \u2014 board confidence rises. The winning faction is now dominant. However, losing factions are demoralised, talent retention risk rises, and long-term cultural cohesion is at risk."},{"id":"opt_hybrid_leadership","label":"Propose hybrid leadership model \u2014 power sharing","keywords":["hybrid","power sharing","co-leadership","shared","joint","committee","coalition"],"state_changes":{"phase":"resolution","variables":{"stakeholder_alignment":68,"board_confidence":68,"team_morale":70,"talent_retention_risk":25,"political_capital":55}},"feedback":"Hybrid model is popular with staff \u2014 team_morale rises to 70 and talent retention risk drops significantly. Board is cautiously supportive. Risk: hybrid models require high alignment to function and may simply delay the conflict."},{"id":"opt_external_hire","label":"Recommend external CEO hire as neutral party","keywords":["external","outside","neutral","new CEO","outside hire","fresh","third party CEO"],"state_changes":{"phase":"resolution","variables":{"stakeholder_alignment":62,"board_confidence":82,"political_capital":45,"team_morale":60,"faction_a_strength":40,"faction_b_strength":40,"faction_c_strength":40}},"feedback":"External hire recommendation is welcomed by the board (82). All internal factions are weakened equally \u2014 political capital across factions drops. Your own influence is diminished but the organisation avoids internal fracture."},{"id":"opt_compromise_restructure","label":"Accept a compromise structural restructure","keywords":["restructure","reorganise","reorg","compromise","restructuring","new structure","accept"],"state_changes":{"phase":"resolution","variables":{"stakeholder_alignment":72,"board_confidence":72,"team_morale":65,"political_capital":60,"talent_retention_risk":28,"narrative_control":70}},"feedback":"Structural compromise achieves the highest stakeholder alignment of all endgame options (72). All parties make concessions. Board confidence is strong. Team morale is healthy. This path requires high political capital to execute."}]}],"event_triggers":[{"id":"evt_media_leak","condition":{"variable":"media_exposure_risk","operator":"gt","value":65},"event":{"type":"media_leak","title":"Internal Conflict Goes Public","description":"A journalist has published an article citing anonymous sources describing \"internal war\" at the company. Board is furious. Share price has fallen 3%.","severity":"critical","variable_changes_delta":{"board_confidence":-18,"talent_retention_risk":20,"public_trust":-10}}},{"id":"evt_key_departure","condition":{"variable":"talent_retention_risk","operator":"gt","value":72},"event":{"type":"key_talent_departure","title":"Star Employee Departure","description":"Your top product architect has accepted an offer from a direct competitor. Two others have requested exit interviews. Technical credibility of the Innovation faction severely damaged.","severity":"high","variable_changes_delta":{"faction_c_strength":-20,"team_morale":-12,"board_confidence":-8}}},{"id":"evt_board_intervention","condition":{"variable":"board_confidence","operator":"lt","value":38},"event":{"type":"board_emergency_session","title":"Board Emergency Session Called","description":"The board has called an emergency governance session. All executives are summoned. The CEO appointment process has been suspended pending review. A crisis management firm has been retained.","severity":"critical","variable_changes_delta":{"political_capital":-20,"executive_support":-15,"media_exposure_risk":30}}},{"id":"evt_alignment_achieved","condition":{"variable":"stakeholder_alignment","operator":"gt","value":72},"event":{"type":"alignment_milestone","title":"Stakeholder Alignment Milestone","description":"A rare moment of genuine cross-faction alignment. All three faction leaders have voluntarily participated in a joint strategy session. Board has taken note and delayed the external hire search.","severity":"positive","variable_changes_delta":{"board_confidence":10,"team_morale":12,"talent_retention_risk":-15}}},{"id":"evt_morale_collapse","condition":{"variable":"team_morale","operator":"lt","value":30},"event":{"type":"morale_crisis","title":"Organisational Morale Crisis","description":"Anonymous internal survey results have been leaked showing 78% of staff are considering leaving within 12 months. HR has declared a culture emergency.","severity":"critical","variable_changes_delta":{"talent_retention_risk":25,"board_confidence":-12,"media_exposure_risk":20}}}],"outcome_conditions":[{"id":"oc_collapse","condition":{"variable":"talent_retention_risk","operator":"gt","value":88,"and":{"variable":"board_confidence","operator":"lt","value":30}},"outcome":"organisational_collapse","severity":"catastrophic","description":"Leadership vacuum combined with mass talent exodus has triggered organisational collapse. Board has initiated emergency restructuring. External advisors have been brought in to manage the crisis. Long-term viability at risk."},{"id":"oc_pyrrhic","condition":{"variable":"political_capital","operator":"gt","value":82,"and":{"variable":"team_morale","operator":"lt","value":28}},"outcome":"pyrrhic_victory","severity":"high","description":"Political objective achieved but at severe human cost. You have won the power contest but the organisation you now lead is demoralised and fractured. The victory may be short-lived."},{"id":"oc_functional_alignment","condition":{"variable":"stakeholder_alignment","operator":"gte","value":60,"and":{"variable":"board_confidence","operator":"gte","value":65}},"outcome":"functional_alignment","severity":"success","description":"Functional alignment achieved. The organisation is not unified but is operationally coherent. Leadership transition can proceed. Continued monitoring of faction dynamics required."},{"id":"oc_strong_resolution","condition":{"variable":"stakeholder_alignment","operator":"gte","value":75,"and":{"variable":"team_morale","operator":"gte","value":68}},"outcome":"organisational_unity","severity":"success","description":"Exceptional outcome. Genuine organisational unity achieved through the leadership transition. All factions have contributed to a coherent strategic direction. The company is positioned for strong execution."}]}'::jsonb,
  NOW(),
  NOW()
);
